// 全球主要城市表（人口 > 10 万，按国家分包）——由 scripts/build-world-cities.mjs 生成，请勿直接编辑。
//
// 来源：GeoNames cities15000 dump（CC BY 4.0）+ admin1CodesASCII.txt 的一级行政区名。
// 坐标是 GeoNames 给出的城市点位（不是行政区中心点），用于「关注点 + 半径」匹配。
//
// 覆盖：166 个国家 / 地区、5224 个城市。
// **不包含日本与中国（含台港澳）**——那两个地区在设置页里有自己的分支与匹配语义
//（日本按行政区名、中国按省 / 地级市），混进来既重复又会让匹配口径含糊。
//
// 城市名：GeoNames alternatenames 里的中文候选优先（取最短的一个），没有则用 asciiname。
// 同一个国家内重名的城市会把一级行政区附在后面（「斯普林菲尔德（Illinois）」），
// 否则列表里两条一模一样的名字无法区分。
//
// admin 只用于**展示与区分**，不参与匹配：匹配永远是「坐标 + 半径」。

